static int genwqe_prev_regs_show ( struct seq_file * s , void * unused ) { struct genwqe_dev * cd = s -> private ; unsigned int i ; struct genwqe_reg * regs = cd -> ffdc [ GENWQE_DBG_REGS ] . regs ; if ( regs == NULL ) { return - EINVAL ; } for ( i = 0 ; i < GENWQE_FFDC_REGS ; i ++ ) { if ( regs [ i ] . addr == 0xffffffff ) { break ; } seq_printf ( s , "  0x%08x 0x%016llx\n" , regs [ i ] . addr , regs [ i ] . val ) ; } return 0 ; } 